//! Checks morphological reconstruction and the regional-maximum transform
//! against QuPath's own output.
//!
//! Fixture generated by `parity/java/RegionalMaxima.java` via
//! `./parity/record.sh`, recorded through
//! `MorphologicalReconstruction.morphologicalReconstruction` and
//! `MorphologicalReconstruction.findRegionalMaxima` — the pair of calls
//! `WatershedCellDetection` makes between the Laplacian of Gaussian and the
//! watershed. Needs no slide.
//!
//! Two levels are compared separately, because a per-pixel comparison of the
//! transform alone would not say which half was wrong:
//!
//! - `morphologicalReconstruction` on hand-built marker/mask pairs, which pins
//!   the geodesic dilation on its own;
//! - `findRegionalMaxima`, which pins the non-strict maximum test, the punch-out
//!   to negative infinity, and the absolute difference that turns the refilled
//!   image into a prominence.
//!
//! # Why this asserts bit-identity
//!
//! For the same reason the convolution's test does. Reconstruction is
//! comparisons, assignments and one absolute difference — no arithmetic that
//! could round two ways, nothing transcendental, no accumulation order to
//! disagree about. Every value either matches ImageJ's bits or the port is
//! wrong, so the test says that rather than allowing a tolerance it does not
//! need. The `1e-5` relative gate is kept outside it so a failure reports how
//! far off it is and not merely that it differs.

use qupath_filters::{Reconstructor, find_regional_maxima};

/// Relative tolerance, per `parity/README.md`.
const TOLERANCE: f64 = 1e-5;

/// Values below this are compared absolutely rather than relatively. A
/// prominence is zero over most of any image — that is the point of it — and
/// relative error is unbounded there for reasons that say nothing about
/// correctness.
const NEAR_ZERO: f64 = 1e-6;

fn fixture() -> std::path::PathBuf {
    std::path::Path::new(env!("CARGO_MANIFEST_DIR"))
        .join("../../parity/fixtures/RegionalMaxima.json")
}

fn read() -> String {
    let path = fixture();
    std::fs::read_to_string(&path)
        .unwrap_or_else(|e| panic!("{}: {e}; run ./parity/record.sh", path.display()))
}

/// Extracts the text between two markers, starting the search at `from`.
fn between<'a>(haystack: &'a str, start: &str, end: &str, from: usize) -> (&'a str, usize) {
    let open = haystack[from..].find(start).expect(start) + from + start.len();
    let close = haystack[open..].find(end).expect(end) + open;
    (&haystack[open..close], close)
}

/// Parses a float list. Java writes `Float.toString`, which round-trips
/// exactly, so these are the same bits ImageJ held — including the
/// `-Infinity` a punched-out maximum carries, which Rust parses back as such.
fn floats(text: &str) -> Vec<f32> {
    text.split(',')
        .map(|v| v.trim().parse().expect("float"))
        .collect()
}

fn scalar(text: &str, key: &str, from: usize) -> (f64, usize) {
    let (value, at) = between(text, &format!("\"{key}\": "), ",", from);
    (value.trim().parse().expect(key), at)
}

#[expect(
    clippy::cast_possible_truncation,
    clippy::cast_sign_loss,
    reason = "recorded dimensions and counts are small positive integers"
)]
fn index(value: f64) -> usize {
    value as usize
}

/// Compares one image against QuPath's, returning the worst relative error.
fn compare(ours: &[f32], theirs: &[f32], what: &str) -> f64 {
    assert_eq!(
        ours.len(),
        theirs.len(),
        "{what}: {} values against QuPath's {}",
        ours.len(),
        theirs.len()
    );

    let mut worst = 0.0f64;
    let mut differing = 0usize;
    for (at, (&ours, &theirs)) in ours.iter().zip(theirs).enumerate() {
        if ours.to_bits() != theirs.to_bits() {
            differing += 1;
        }
        let (ours, theirs) = (f64::from(ours), f64::from(theirs));
        let difference = (ours - theirs).abs();
        let relative = if theirs.abs() > NEAR_ZERO {
            difference / theirs.abs()
        } else {
            difference
        };
        assert!(
            relative <= TOLERANCE,
            "{what}: at {at} we have {ours}, QuPath has {theirs} (relative {relative:.3e})"
        );
        worst = worst.max(relative);
    }

    assert_eq!(
        differing,
        0,
        "{what}: {differing} of {} values differ from QuPath in their bits. \
         Reconstruction is comparisons and assignments with one absolute \
         difference at the end, so there is no rounding freedom to explain it \
         — check the neighbour order, the mask clip, and the queue.",
        ours.len()
    );
    worst
}

#[test]
fn matches_qupath_morphological_reconstruction() {
    let text = read();
    let (cases, _) = between(&text, "\"reconstructions\": [", "\n  ],", 0);

    let mut count = 0usize;
    let mut at = 0usize;
    // One reconstructor across every case on purpose: a queue left dirty by a
    // previous shape would show up here and nowhere else.
    let mut reconstructor = Reconstructor::new();
    while let Some(start) = cases[at..].find("{\"name\": \"") {
        let from = at + start;
        let (name, next) = between(cases, "\"name\": \"", "\"", from);
        let (width, next) = scalar(cases, "width", next);
        let (height, next) = scalar(cases, "height", next);
        let (marker_text, next) = between(cases, "\"marker\": [", "]", next);
        let (mask_text, next) = between(cases, "\"mask\": [", "]", next);
        let (output_text, next) = between(cases, "\"out\": [", "]", next);
        at = next;

        let (width, height) = (index(width), index(height));
        let mask = floats(mask_text);
        let mut ours = floats(marker_text);
        assert_eq!(
            ours.len(),
            width * height,
            "{name}: {} marker values for {width}x{height}",
            ours.len()
        );

        reconstructor.reconstruct(&mut ours, &mask, width);

        let label = format!("{name} ({width}x{height})");
        let worst = compare(&ours, &floats(output_text), &label);
        println!("{name:>28}  {width:>3}x{height:<3}  worst relative {worst:.3e}");
        count += 1;
    }

    assert!(count >= 11, "only {count} reconstructions in the fixture");

    for (name, why) in [
        (
            "flood-forward",
            "the >10% loop that repeats the raster passes",
        ),
        (
            "flood-backward",
            "the backward-then-queue path, when the forward pass changes nothing",
        ),
        (
            "blocked-by-wall",
            "the dilation is geodesic, not a dilate-then-clip",
        ),
        (
            "serpentine",
            "a path no raster pass can follow in one direction",
        ),
        (
            "diagonal-serpentine",
            "the queue propagates diagonally; the raster passes hide this",
        ),
        (
            "marker-above-mask",
            "reconstruction raises but never lowers; QuPath does not validate",
        ),
        (
            "holes-at-negative-infinity",
            "the only marker findRegionalMaxima ever passes",
        ),
        ("single-pixel", "an image with no interior at all"),
    ] {
        assert!(cases.contains(name), "{name} missing: {why} is unchecked");
    }
}

#[test]
fn matches_qupath_regional_maxima() {
    let text = read();
    let (cases, _) = between(&text, "\"maxima\": [", "\n  ]\n}", 0);

    let mut count = 0usize;
    let mut overall = 0.0f64;
    let mut at = 0usize;
    while let Some(start) = cases[at..].find("{\"name\": \"") {
        let from = at + start;
        let (name, next) = between(cases, "\"name\": \"", "\"", from);
        let (width, next) = scalar(cases, "width", next);
        let (height, next) = scalar(cases, "height", next);
        let (threshold, next) = scalar(cases, "threshold", next);
        let (labels, next) = scalar(cases, "labelCount", next);
        let (input_text, next) = between(cases, "\"in\": [", "]", next);
        let (prominence_text, next) = between(cases, "\"prominence\": [", "]", next);
        at = next;

        let (width, height) = (index(width), index(height));
        let input = floats(input_text);
        assert_eq!(
            input.len(),
            width * height,
            "{name}: {} input values for {width}x{height}",
            input.len()
        );

        #[expect(
            clippy::cast_possible_truncation,
            reason = "the recorded threshold is 0.001f, written back out by Java as a float"
        )]
        let ours = find_regional_maxima(&input, width, threshold as f32);

        let label = format!("{name} ({width}x{height})");
        let worst = compare(&ours, &floats(prominence_text), &label);
        println!(
            "{name:>22}  {width:>3}x{height:<3}  {:>3} maxima  worst relative {worst:.3e}",
            index(labels)
        );
        overall = overall.max(worst);
        count += 1;
    }

    assert!(count >= 13, "only {count} maxima cases in the fixture");

    for (name, why) in [
        (
            "shoulder-plateau",
            "a terrace is a candidate maximum and has no prominence; \
             this is the whole reason the stage exists",
        ),
        ("plateau", "the maximum test is not strict"),
        (
            "two-peaks-one-saddle",
            "prominence is measured from the saddle, not from zero",
        ),
        (
            "two-peaks-no-saddle",
            "no descent between them means one maximum, not two",
        ),
        ("below-threshold", "the 0.001 gate on the value"),
        ("border-peaks", "the scan skips the one-pixel frame"),
        ("ramp", "a monotone surface has no interior maximum"),
        (
            "log-tile",
            "the input this stage actually meets in the pipeline",
        ),
    ] {
        assert!(cases.contains(name), "{name} missing: {why} is unchecked");
    }

    println!("{count} surfaces  worst relative {overall:.3e}, all bit-identical");
}
